def transform(grid):
    """Extend diagonal strokes outward from every adjacent non-background pair."""
    from collections import Counter
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    pairs = []
    for r in range(h):
        for c in range(w):
            if out[r][c] == bg:
                continue
            for dc in (-1, 1):
                rr, cc = r + 1, c + dc
                if 0 <= rr < h and 0 <= cc < w and out[rr][cc] == out[r][c] and out[rr][cc] != bg:
                    pairs.append(((r, c), (rr, cc)))
    for (r1, c1), (r2, c2) in pairs:
        for r, c, dr, dc in ((r1, c1, r1-r2, c1-c2),
                             (r2, c2, r2-r1, c2-c1)):
            color = out[r][c]
            rr, cc = r + dr, c + dc
            while 0 <= rr < h and 0 <= cc < w and out[rr][cc] == bg:
                out[rr][cc] = color
                rr += dr
                cc += dc
    return out

def transform(grid):
    """From each same-color diagonal pair, extend the diagonal down from its lower cell to the edge."""
    out = [row[:] for row in grid]
    h, w = len(out), len(out[0])
    from collections import Counter
    bg = Counter(v for row in out for v in row).most_common(1)[0][0]
    rays = []
    for r in range(h - 1):
        for c in range(w):
            for dc in (-1, 1):
                cc = c + dc
                if 0 <= cc < w and out[r][c] != bg and out[r][c] == out[r + 1][cc]:
                    rays.append((r + 1, cc, dc, out[r][c]))
    for r, c, dc, color in rays:
        r += 1
        c += dc
        while 0 <= r < h and 0 <= c < w:
            out[r][c] = color
            r += 1
            c += dc
    return out

